import math

def safe_speed(text):
    try:
        value = float(text)
    except ValueError:
        return None
    if not math.isfinite(value) or value <= 0:
        return None
    return value

raw_speed = input("Speed: ")
speed = safe_speed(raw_speed)
print("Speed:", speed)
